function deriveWorkspaceName(name: string): string {
  const full = `${name}${WORKSPACE_NAME_SUFFIX}`;
  if (full.length <= ORGANIZATION_NAME_MAX_LENGTH) return full;

  const trimmedName = name.slice(
    0,
    ORGANIZATION_NAME_MAX_LENGTH - WORKSPACE_NAME_SUFFIX.length,
  );
  return `${trimmedName}${WORKSPACE_NAME_SUFFIX}`;
}

