import { beforeEach, describe, expect, it } from "vitest";
import { resetTestDb, setupTestDb } from "./helpers/db";
import { register, login } from "@/server/services/auth-service";
import { resetRateLimits } from "@/lib/rate-limit";
import * as orgRepo from "@/server/repositories/organization-repository";

beforeEach(async () => {
  await setupTestDb();
  await resetTestDb();
  resetRateLimits();
});

describe("sign-up sanity", () => {
  it("signs up a person named Admin", async () => {
    const { org } = await register({
      name: "Admin",
      email: "admin-person@example.com",
      password: "Abcdefgh1234",
      confirmPassword: "Abcdefgh1234",
      acceptTerms: true,
    });
    expect(org.slug).not.toBe("admin");
    expect(org.name).toBe("Admin's workspace");
  });

  it("signs up a person named J", async () => {
    const { org } = await register({
      name: "J",
      email: "j-person@example.com",
      password: "Abcdefgh1234",
      confirmPassword: "Abcdefgh1234",
      acceptTerms: true,
    });
    expect(org.slug.length).toBeGreaterThanOrEqual(2);
    expect(org.name).toBe("J's workspace");
  });

  it("signs up a person with no Latin letters in their name", async () => {
    const { org } = await register({
      name: "山田",
      email: "yamada@example.com",
      password: "Abcdefgh1234",
      confirmPassword: "Abcdefgh1234",
      acceptTerms: true,
    });
    expect(org.slug).toBe("workspace");
  });

  it("case-insensitive email: mixed case at signup, lowercase at login works", async () => {
    await register({
      name: "Alice",
      email: "Alice@Example.COM",
      password: "Abcdefgh1234",
      confirmPassword: "Abcdefgh1234",
      acceptTerms: true,
    });

    const { user } = await login({
      email: "alice@example.com",
      password: "Abcdefgh1234",
      rememberMe: false,
    });
    expect(user.email).toBe("alice@example.com");
  });

  it("refuses a second signup with the same address (any case) as a conflict", async () => {
    await register({
      name: "Bob",
      email: "bob@example.com",
      password: "Abcdefgh1234",
      confirmPassword: "Abcdefgh1234",
      acceptTerms: true,
    });

    await expect(
      register({
        name: "Bobby",
        email: "BOB@EXAMPLE.COM",
        password: "Abcdefgh1234",
        confirmPassword: "Abcdefgh1234",
        acceptTerms: true,
      }),
    ).rejects.toMatchObject({ code: "conflict" });
  });

  it("truncates a very long name's workspace so it still ends in 's workspace' and fits", async () => {
    const longName = "A".repeat(80);
    const { org } = await register({
      name: longName,
      email: "longname@example.com",
      password: "Abcdefgh1234",
      confirmPassword: "Abcdefgh1234",
      acceptTerms: true,
    });
    expect(org.name.length).toBeLessThanOrEqual(64);
    expect(org.name.endsWith("'s workspace")).toBe(true);
  });

  it("throttles register after many attempts with rate_limited code", async () => {
    let caught: unknown = null;
    for (let i = 0; i < 40; i += 1) {
      try {
        await register({
          name: `Person${i}`,
          email: `person${i}@example.com`,
          password: "Abcdefgh1234",
          confirmPassword: "Abcdefgh1234",
          acceptTerms: true,
        });
      } catch (error) {
        caught = error;
        break;
      }
    }
    expect(caught).toMatchObject({ code: "rate_limited" });
  });

  it("two people with no-Latin names both get workspace / workspace-2", async () => {
    const r1 = await register({
      name: "山田",
      email: "p1@example.com",
      password: "Abcdefgh1234",
      confirmPassword: "Abcdefgh1234",
      acceptTerms: true,
    });
    const r2 = await register({
      name: "田中",
      email: "p2@example.com",
      password: "Abcdefgh1234",
      confirmPassword: "Abcdefgh1234",
      acceptTerms: true,
    });
    expect([r1.org.slug, r2.org.slug].sort()).toEqual(["workspace", "workspace-2"]);
  });
});

